def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    banned = ["ERPNext"]
    blob = json.dumps({"l": lessons, "q": questions})
    for b in banned:
        if b in blob:
            problems.append(f"  {name}: '{b}' leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.175.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.174.0"' not in init:
        sys.exit("ABORT: not at v3.174.0.")
    for k in ("attendance", "leave"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("HR3", LESSONS_H3, QUESTIONS_H3, 9) + _validate("HR4", LESSONS_H4, QUESTIONS_H4, 10)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("HR 3", LESSONS_H3, QUESTIONS_H3, "attendance",
         "Attendance in ZhiftERP: the four record types and the per-location method decision; Holiday List construction with the annual build procedure; Attendance records and the Employee Checkin log with its device, mobile, and manual sources; the Shift Type's auto-attendance block — determination, working-hours thresholds, grace periods, checkin windows, Process Attendance After, Last Sync of Checkin — with the test cycle; Default Shift and Shift Assignment with the coverage, orphan, and alignment reads; manual marking with the Employee Attendance Tool and the unmarked-day controls; and the Attendance Request lane with the daily, weekly, and monthly reads including the Monthly Attendance Sheet."),
        ("HR 4", LESSONS_H4, QUESTIONS_H4, "leave",
         "Leave in ZhiftERP: the five-record dependency order; the Leave Type's twelve behaviour flags configured from the written policy with the type register; Leave Period, Leave Policy, and the Leave Policy Assignment generating allocations in the annual round with its completeness verification; Leave Allocation mechanics including carry-forward caps and the lawful manual cases; the Leave Application workflow — computed day counts, approver reads, the records-close rule, blocked-application diagnosis; Leave Without Pay with its payment-days consequence; compensatory leave earned on evidence and in-service encashment on the policy line; and the Employee Leave Balance report with the leave ledger."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.174.0"', '"3.175.0"'))
    print("  data: HR 3 + 4 lessons + banks REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.175.0")


if __name__ == "__main__":
    main()
